<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"/>
<title>The Great Wave off Kanagawa — low poly 3D wallpaper</title>
<link rel="preconnect" href="https://fonts.googleapis.com"/>
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin/>
<link href="https://fonts.googleapis.com/css2?family=Shippori+Mincho:wght@400;500&family=Spectral:wght@300;400&display=swap" rel="stylesheet"/>
<style>
  :root{ --ink:#173059; --cream:#efe6cf; }
  *{ box-sizing:border-box; margin:0; padding:0; }
  html,body{ width:100%; height:100%; background:#0c1a2e; overflow:hidden; }
  body{ font-family:'Spectral',Georgia,serif; color:var(--ink); }
  #app{ position:fixed; inset:0; }
  canvas{ display:block; width:100%; height:100%; }
  .plate{
    position:fixed; left:50%; bottom:clamp(18px,4vh,40px); transform:translateX(-50%);
    text-align:center; z-index:5; pointer-events:none; user-select:none;
    opacity:.92; mix-blend-mode:multiply;
  }
  .plate .jp{ font-family:'Shippori Mincho',serif; font-size:clamp(15px,2.4vw,26px); letter-spacing:.18em; }
  .plate .en{ font-size:clamp(9px,1.1vw,13px); letter-spacing:.34em; text-transform:uppercase; opacity:.6; margin-top:6px; }
  .plate .by{ font-size:clamp(8px,.9vw,11px); letter-spacing:.18em; opacity:.45; margin-top:3px; font-style:italic; }
  .sig{
    position:fixed; top:clamp(14px,3vh,30px); right:clamp(14px,3vw,34px); z-index:5;
    writing-mode:vertical-rl; font-family:'Shippori Mincho',serif;
    font-size:clamp(10px,1.3vw,16px); letter-spacing:.22em; opacity:.5;
    border-right:1px solid rgba(23,48,89,.35); padding-right:8px; pointer-events:none;
  }
  @media (max-width:640px){ .sig{ display:none; } }
</style>
