camera.lookAt(0, 2.2, 0);
const BASE_FRUSTUM = 16;

/* ──────────────── lights ──────────────── */
scene.add(new THREE.AmbientLight(C.foam.clone(), 0.62));
const sun = new THREE.DirectionalLight(C.gold.clone(), 0.95);
sun.position.set(-26, 34, 40);
scene.add(sun);
const shade = new THREE.DirectionalLight(C.deepBlue.clone(), 0.45);
shade.position.set(30, 18, -20);
scene.add(shade);
const skyFill = new THREE.HemisphereLight(C.pale.clone(), C.deepBlue.clone(), 0.30);
skyFill.position.set(0, 20, 0);
scene.add(skyFill);

